import functools as _functools
import warnings as _warnings


def _httpx_shim_map_proxies(kwargs):
    proxies = kwargs.pop("proxies")
    _warnings.warn(
        "The 'proxies' argument is deprecated; use 'proxy' or 'mounts' instead.",
        DeprecationWarning,
        stacklevel=3,
    )
    if proxies is None:
        return
    if isinstance(proxies, dict):
        mounts = dict(kwargs.get("mounts") or {})
        for pattern, value in proxies.items():
            if value is None:
                mounts[pattern] = None
            else:
                mounts[pattern] = None  # placeholder, replaced below
                mounts[pattern] = value
        kwargs["_httpx_shim_proxy_mounts"] = mounts
    else:
        kwargs.setdefault("proxy", proxies)


def _httpx_shim_patch(cls, transport_cls, async_):
    original = cls.__init__

    @_functools.wraps(original)
    def __init__(self, *args, **kwargs):
        if "proxies" in kwargs:
            _httpx_shim_map_proxies(kwargs)
        proxy_mounts = kwargs.pop("_httpx_shim_proxy_mounts", None)
        if "app" in kwargs:
            app = kwargs.pop("app")
            _warnings.warn(
                "The 'app' argument is deprecated; use 'transport=%s(app=...)' instead." % (
                    "ASGITransport" if async_ else "WSGITransport"
                ),
                DeprecationWarning,
                stacklevel=2,
            )
            if app is not None and kwargs.get("transport") is None:
                kwargs["transport"] = (ASGITransport if async_ else WSGITransport)(app=app)
        if proxy_mounts:
            verify = kwargs.get("verify", True)
            trust_env = kwargs.get("trust_env", True)
            mounts = dict(kwargs.get("mounts") or {})
            for pattern, value in proxy_mounts.items():
                if value is None:
                    mounts[pattern] = None
                elif isinstance(value, (transport_cls,)) or hasattr(value, "handle_request") or hasattr(value, "handle_async_request"):
                    mounts[pattern] = value
                else:
                    mounts[pattern] = transport_cls(
                        proxy=value if isinstance(value, Proxy) else Proxy(value),
                        verify=verify,
                        trust_env=trust_env,
                    )
            kwargs["mounts"] = mounts
        original(self, *args, **kwargs)

    cls.__init__ = __init__


_httpx_shim_patch(Client, HTTPTransport, False)
_httpx_shim_patch(AsyncClient, AsyncHTTPTransport, True)
